WITH cleaned AS (SELECT *, HOUR(event_time) AS event_time_hour, COALESCE(page, 'OTHER') AS page_clean FROM web_events WHERE event_time >= TIMESTAMP '2023-09-13 08:00:00' AND page IS NOT NULL AND duration_sec > 189), flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM cleaned), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS new_group_flag_tier, MIN(event_time) AS started_at, BIT_AND(duration_sec) AS duration_sec_bit_and, APPROX_PERCENTILE(event_time_hour, ARRAY(0.25, 0.5, 0.75)) AS event_time_hour_quartiles, AVG(event_time_hour) AS avg_event_time_hour, SUM(CASE WHEN event_type = 'click' THEN event_time_hour ELSE 0 END) AS click_event_time_hour, MAX(event_time_hour) FILTER (WHERE page = '/checkout') AS checkout_max_event_time_hour FROM islands GROUP BY CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END;
